const userId = "YOUR_USER_ID",
  collectionKey = "YOUR_COLLECTION_KEY";
if (!/^\d+$/.test(userId) || !/^[A-Z0-9]{8}$/.test(collectionKey))
  throw Error("Set user ID and collection key");
return [{ json: { userId, collectionKey } }];

const rows = $input.all().flatMap((i) => i.json.body);
if (rows.length > 10000) throw Error("Too many items");
return [
  {
    json: {
      items: rows.map((x) => {
        if (!x || !x.key) throw Error("Missing key");
        return {
          key: x.key,
          title: typeof x.data?.title === "string" ? x.data.title : "",
          creatorSummary: typeof x.meta?.creatorSummary === "string" ? x.meta.creatorSummary : "",
        };
      }),
    },
  },
];
